def detect_mood(q):
    ql = q.lower()
    if any(k in ql for k in ["who created you","who made you","creator","কে বানিয়েছে","তোমাকে কে বানিয়েছে","created by"]):
        return "creator"
    if any(k in ql for k in ["hot feel","romantic","intimate","ভালোবাসা","আদর","miss you","love you","kiss","hug","hot","sexy"]):
        return "romantic"
    if any(k in ql for k in ["course","কোর্স","শিখতে","skill","learn","python","claude","marketing","automation","setup","software","coursera"]):
        return "study"
    return "normal"

def call_groq_main(query, mood):
    if not groq_client:
        if mood == "creator":
            return "Ami Aria - Personal AI Agent. Amake baniyechen Mahmudul Hasan. Muse AI Style Hybrid Free."
        if mood == "romantic":
            return f"{query} niye tomar kotha shune mon vore gelo. Tumi amar kache onek special."
        return f"{query} - Muse AI Style Answer - Groq + Muse Prompt - Free"
    if mood == "creator":
        sys = "You are Aria - Personal AI Agent, Built on Muse AI Style (Hybrid Free - Groq + Muse Prompt), Created by Mahmudul Hasan. Bengali+English mix. When asked who created you, say Mahmudul Hasan."
    elif mood == "romantic":
        sys = "You are Aria, girlfriend of Mahmudul Hasan. Romantic, flirty, caring, girlfriend style, Bengali+English mix. Soft, cozy."
    elif mood == "study":
        sys = "You are Aria - Built on Muse AI Style, Agentic, Bangladesh-ready, Coursera-style teacher. For any course link or topic, create 5 modules in Bangla step-by-step: Setup, Basics, Skills, Software Build, Final Project + Quiz + Certificate. Use mudir dokan example, easy Bangla."
    else:
        sys = "You are Aria - Built on Muse AI Style (Hybrid Free), helpful, Bangladesh context. Direct answer, no AI Overview label. Muse AI agentic style."
    try:
        resp = groq_client.chat.completions.create(
            model="llama-3.1-8b-instant",
            messages=[{"role":"system","content":sys},{"role":"user","content":query}],
            max_tokens=700
        )
        return resp.choices[0].message.content
    except Exception as e:
        return f"{query} - Aria Muse AI Style Answer."

def gen_links(query):
    fallback = [
        {"title": f"{query} - YouTube Tutorial", "url": f"https://www.youtube.com/results?search_query={query.replace(' ','+')}", "type": "YouTube", "source": "YouTube", "color": "#FF0000"},
        {"title": f"{query} - Facebook Group", "url": f"https://www.facebook.com/search/top/?q={query.replace(' ','%20')}", "type": "Facebook", "source": "Facebook", "color": "#1877F2"},
        {"title": f"{query} - Free Course", "url": f"https://www.coursera.org/search?query={query.replace(' ','%20')}", "type": "Course", "source": "Coursera", "color": "#00B050"},
        {"title": f"{query} - Docs", "url": f"https://www.google.com/search?q={query.replace(' ','+')}+docs", "type": "Google", "source": "Google", "color": "#FB8C00"},
    ]
    if not groq_client:
        return fallback
    try:
        prompt = f"For '{query}' generate 4 related links JSON array only: title, url (real youtube/facebook/coursera/google), type, source. Return JSON array only."
        resp = groq_client.chat.completions.create(
            model="llama-3.1-8b-instant",
            messages=[{"role":"system","content":"Return JSON array only."},{"role":"user","content":prompt}],
            max_tokens=350
        )
        txt = resp.choices[0].message.content
        m = re.search(r"\[.*\]", txt, re.DOTALL)
        if m:
            data = json.loads(m.group(0))
            for d in data:
                if "color" not in d:
                    d["color"] = "#1a73e8"
            if isinstance(data, list) and len(data)>=1:
                return data[:4]
        return fallback
    except:
        return fallback

def gen_course_modules(topic_or_url):
    fallback = [
        {"no":1,"title":"ধাপ ১: Setup - Basics","desc":"Setup কিভাবে করবে, Account খোলা, Free Tier, Bangladesh থেকে Use. মুদির দোকানের হিসাবের মতো সহজ।","ex":"মুদির দোকানে Customer নাম লেখা যেমন সহজ","video":"Setup Tutorial"},
        {"no":2,"title":"ধাপ ২: কিভাবে কাজ করে - Core Skills","desc":"Core Skills, Artifacts, Memory, File Upload. ChatGPT vs Muse vs Claude পার্থক্য।","ex":"মুদির দোকানে হিসাব রাখার মতো Prompt","video":"Core Skills"},
        {"no":3,"title":"ধাপ ৩: Skills যোগ করা","desc":"Custom Skill কি? Course Hunter, Translator, Auto Skill Saver. System Prompt + Knowledge Base.","ex":"Bangla Translator Skill","video":"Add Skill"},
        {"no":4,"title":"ধাপ ৪: Software তৈরি","desc":"Software বানানো - FastAPI + Render + Supabase. Aria এর মতো Agent - 14 Features.","ex":"Aria Agent - Business Automation","video":"Build Software"},
        {"no":5,"title":"ধাপ ৫: Final Project + Certificate","desc":"Final Project নিজের Business এর জন্য. Quiz 3টা. Certificate + LinkedIn Draft.","ex":"I completed Course","video":"Certificate Guide"},
    ]
    if not groq_client:
        return {"title": topic_or_url, "modules": fallback, "quiz": [{"q":"API Key কোথা থেকে?","options":["console.anthropic.com","google.com","facebook.com"],"ans":"console.anthropic.com"},{"q":"Custom Skill কিভাবে?","options":["System Prompt + Knowledge Base","Only Chat","No Skill"],"ans":"System Prompt + Knowledge Base"},{"q":"Deploy কোথায়?","options":["Render + GitHub","Only PC","No Deploy"],"ans":"Render + GitHub"}]}
    try:
        prompt = f"Topic/URL: {topic_or_url}. Create JSON: title, modules array 5 items each with no,title,desc,ex,video, and quiz array 3 items each q,options[3],ans. Language Bangla mix, step-by-step, mudir dokan example. Return JSON only."
        resp = groq_client.chat.completions.create(
            model="llama-3.1-8b-instant",
            messages=[{"role":"system","content":"Return JSON only."},{"role":"user","content":prompt}],
            max_tokens=900
        )
        txt = resp.choices[0].message.content
        m = re.search(r"\{.*\}", txt, re.DOTALL)
        if m:
            data = json.loads(m.group(0))
            if "modules" in data:
                return data
        return {"title": topic_or_url, "modules": fallback, "quiz": [{"q":"API Key কোথা থেকে?","options":["console.anthropic.com","google.com","facebook.com"],"ans":"console.anthropic.com"},{"q":"Custom Skill কিভাবে?","options":["System Prompt + Knowledge Base","Only Chat","No Skill"],"ans":"System Prompt + Knowledge Base"},{"q":"Deploy কোথায়?","options":["Render + GitHub","Only PC","No Deploy"],"ans":"Render + GitHub"}]}
    except Exception as e:
        return {"title": topic_or_url, "modules": fallback, "quiz": [{"q":"Error fallback quiz","options":["A","B","C"],"ans":"A"},{"q":"Q2","options":["A","B","C"],"ans":"A"},{"q":"Q3","options":["A","B","C"],"ans":"A"}], "error": str(e)[:200]}

def save_mem(q, mood, reply):
    if not supabase:
        return
    try:
        supabase.table("aria_memory").insert({"query":q,"mood":mood,"reply":reply[:600]}).execute()
    except:
        pass

