@app.get("/memory")
def memory():
    if not supabase:
        return {"supabase_connected": False}
    try:
        d = supabase.table("aria_memory").select("*").order("created_at", desc=True).limit(30).execute()
        return {"supabase_connected": True, "count": len(d.data), "data": d.data}
    except Exception as e:
        return {"supabase_connected": False, "error": str(e)}

